import { wfa, FlowObject, Subflow } from '@servicenow/sdk/automation'
import { BooleanColumn, StringColumn } from '@servicenow/sdk/core'
import { createADUserAccount, provisionDevice } from './complex_object_scenarios.now'

export const setupITResourcesSubflow = Subflow(
    {
        $id: Now.ID['setup_it_resources'],
        name: 'Setup IT Resources',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        inputs: {
            employeeDetails: FlowObject({
                fields: {
                    name: StringColumn({
                        label: 'Name',
                        mandatory: true,
                    }),
                    id: StringColumn({
                        label: 'Employee ID',
                        mandatory: true,
                    }),
                    department: StringColumn({
                        label: 'Department',
                        mandatory: true,
                    }),
                },
                label: 'Employee Details',
                mandatory: true,
            }),
            isRemote: BooleanColumn({ label: 'Is Remote', mandatory: true }),
        },
        outputs: {
            provisioningStatus: StringColumn({ label: 'Provisioning Status', mandatory: true }),
        },
        flowVariables: {
            test3: StringColumn({
                label: 'Test3',
                maxLength: 65000,
            }),
            test: StringColumn({
                label: 'Test',
                maxLength: 65000,
            }),
            test2: StringColumn({
                label: 'Test2',
                maxLength: 65000,
            }),
        },
    },
    (_params) => {
        // Action 1: Create AD user
        const actionInstance_1 = wfa.action(
            createADUserAccount,
            {
                $id: Now.ID['act_create_ad'],
                annotation: 'Create Active Directory user account',
            },
            {
                roles: ['Employee', `EmailUser${wfa.dataPill(_params.flowVariables.test2, 'string')}`],
                username: `Josh, Doe${wfa.dataPill(_params.flowVariables.test, 'string')}`,
            }
        )

        // Action 2: Provision device
        wfa.action(
            provisionDevice,
            {
                $id: Now.ID['act_prov_device'],
                annotation: 'Provision desktop device with accessories',
            },
            {
                deviceType: 'Desktop',
                accessoryList: [
                    `Mouse${wfa.dataPill(_params.flowVariables.test3, 'string')}`,
                    `Keyboard${wfa.dataPill(_params.inputs.employeeDetails.id, 'string')}`,
                    `Headset${wfa.dataPill(actionInstance_1.success, 'boolean')}`,
                ],
            }
        )
    }
)
